async function api(path,body,auth=true){
 const epoch=sessionEpoch;
 const headers={'Content-Type':'application/json','X-AESD-Cost-Precision':'extended-v1'};if(auth&&session)headers.Authorization='Bearer '+session.token;
 let response;try{response=await fetch(apiOrigin+'/aesd/v1'+path,{method:body===undefined?'GET':'POST',headers,body:body===undefined?undefined:JSON.stringify(body),signal:AbortSignal.timeout(45000),cache:'no-store'});offlineConnectivity=false;}catch{if(auth)assertCurrent(epoch);offlineConnectivity=true;const e=Error('Sunucuya ulaşılamadı. Bağlantıyı kontrol edin.');e.network=true;throw e;}
 const invalid=()=>{const e=Error(response.status===404?'Merkezi giriş servisi bu sunucuda bulunamadı. Uygulamayı silmeden destek ile iletişime geçin.':'Sunucu geçerli bir AESD yanıtı vermedi. Giriş yapılmadı. Tekrar deneyin.');e.status=response.status;e.uncertain=true;return e;};
 if(auth&&epoch!==sessionEpoch){const e=Error('Oturum veya panel değişti.');e.stale=true;throw e;}
 const rejected=async error=>{if(auth&&session&&(error.status===401||error.status===403)){await denyMainAccess(error);error.accessDenied=true;}return error;};
 if(!response.headers.get('Content-Type')?.toLowerCase().includes('application/json'))throw invalid();
 let data;try{data=await response.json();}catch{if(auth)assertCurrent(epoch);throw invalid();}
 if(auth&&epoch!==sessionEpoch){const e=Error('Oturum veya panel değişti.');e.stale=true;throw e;}
 if(!data||typeof data!=='object'||Array.isArray(data))throw invalid();
 if(!response.ok||data.ok===false||data.error){const e=Error(typeof data.error==='string'?data.error:'İşlem tamamlanmadı.');e.status=response.status;throw await rejected(e);}
 if(path==='/login'||path==='/me'){
  if(!validUser(data.user)||!Number.isFinite(data.serverTime)||data.user.role==='CLIENT'&&(!data.business||typeof data.business.id!=='string'||!Array.isArray(data.business.panels)))throw invalid();
  if(path==='/login'&&(typeof data.token!=='string'||!/^[a-zA-Z0-9_-]{32,200}$/.test(data.token)||!Number.isFinite(data.expires)||data.expires<=data.serverTime))throw invalid();
 }
 if(path.startsWith('/password-reset/')&&data.ok!==true)throw invalid();
 return data;
}
function assertCurrent(epoch,active){if(epoch!==sessionEpoch||active!==undefined&&active!==store){const error=Error('Oturum veya panel değişti.');error.stale=true;throw error;}}
async function denyMainAccess(error){
 window.dispatchEvent(new Event('aesd-owner-invalidated'));sessionEpoch++;lease=null;window.aesdOwnerAllowed=()=>false;store?.close();store=null;state=null;dataScope=null;disposePrivate();hidePrivate();closeMenu();stopCamera();if(dialog.open)dialog.close();
 if(error.status===401){root.className='';root.innerHTML='<section class="auth card"><h1>Tekrar Giriş Yap</h1><p>Oturum sona erdi. Bekleyen satış kayıtları cihazda korunur.</p></section>';try{if(await clearSession())authView();}catch{error.message+=' Oturum kaydı cihazda silinemedi. Tekrar giriş kontrolü gerekir.';}toast(error.message,'error');}else panelGate(error.message);
}
