 const validAudience=user=>config.audience==='customer'?user.role==='CLIENT':true;
function recoveryView(e='',confirm=false,message=''){
 modal('Şifreni Yenile',`<p class="muted">${confirm?'E-postana gelen 6 haneli kodu ve yeni şifreni gir.':'Hesabında kayıtlı e-posta adresini gir. Kod 10 dakika geçerlidir.'}</p><form data-form="${confirm?'reset-confirm':'reset-request'}">${field('Kayıtlı e-posta','email','email',e,'required maxlength="254" autocomplete="username"'+(confirm?' readonly':''))}${confirm?field('Doğrulama kodu','code','text','','required inputmode="numeric" pattern="[0-9]{6}" maxlength="6" autocomplete="one-time-code"')+field('Yeni şifre','newPassword','password','','required minlength="8" maxlength="64" autocomplete="new-password"')+field('Yeni şifre tekrar','confirm','password','','required minlength="8" maxlength="64" autocomplete="new-password"'):''}${submit(confirm?'Şifreyi Yenile':'Kod Gönder')}</form><p id="recovery-error" class="error" role="alert"></p>${message?`<p class="note" role="status">${escape(message)}</p>`:''}${confirm?button('Yeni Kod İste','reset-again',`data-email="${escape(e)}"`,'quiet'):button('Kodum var','reset-have-code','','quiet')}${contact()}<p class="note">Bu işlem sunucu hesabının şifresini yeniler. Tüm panellere girişte sahip hesabın kullanılır. Özel panelin cihaz güvenlik ayarları korunur. Satış ve stok kayıtları silinmez.</p>`);
}
async function persistSession(){
 const current=session,epoch=sessionEpoch;
 await savePreferences({deviceId,sector,ownerPanel,session:current?.remember?current:null});
 assertCurrent(epoch);if(session!==current)throw Object.assign(Error('Oturum değişti.'),{stale:true});
 localStorage.removeItem('aesd.session.v2');sessionStorage.removeItem('aesd.session.v2');
 (current?.remember?localStorage:sessionStorage).setItem('aesd.session.v2',JSON.stringify(current));
}
async function clearSession(){
 window.dispatchEvent(new Event('aesd-owner-invalidated'));const epoch=++sessionEpoch,previous=session;
 privateCloudStore?.close();privateCloudStore=null;migrationChoice?.('cancel');migrationChoice=null;closeMenu();hidePrivate();privateFrame?.remove();privateFrame=null;privateReady=false;
 await savePreferences({deviceId,sector,ownerPanel,session:null});
 if(epoch!==sessionEpoch||session!==previous)return false;
 localStorage.removeItem('aesd.session.v2');sessionStorage.removeItem('aesd.session.v2');
 if(previous?.user){localStorage.removeItem('aesd.lease.'+previous.user.id);await cloudMeta('owner:'+previous.user.id+':private-template',null);}
 if(epoch!==sessionEpoch||session!==previous)return false;
 session=null;info=null;lease=null;store?.close();store=null;state=null;dataScope=null;resetBasket();window.aesdOwnerAllowed=()=>false;return true;
}
// A delayed logout must not clear a newer login after a concurrent 401.
async function logoutSession(){
 const epoch=sessionEpoch,identity=session?.token;
 try{await api('/logout',{});}catch{if(epoch!==sessionEpoch||identity!==session?.token)return false;toast('Çevrimdışı çıkış yapıldı. Sunucudaki oturum süresi dolana kadar geçerli olabilir.');}
 if(epoch!==sessionEpoch||identity!==session?.token)return false;
 return await clearSession()===true&&session===null;
}
function authView(register=false,loginMode='email'){
 appearance.setAccount(null);hidePrivate();closeMenu();root.className=register?'auth-shell':'auth-shell simple-auth';root.innerHTML=`<section class="auth"><div class="auth-mark"><img src="./icon-512.png" width="88" height="88" alt="AESD"><div class="brand"><em>A</em>ESD</div><p class="tagline">İşyerin için satış ve yönetim</p></div><div class="card"><h1>${register?'İşyerini Kaydet':'Hoş geldin'}</h1><p class="muted">${register?'Her işyeri kendi hesabını ve verilerini kullanır.':'AESD hesabınla giriş yap.'}</p>${register?`<div class="sector ${config.audience==='owner'?'owner-sector':''}">${config.audience==='owner'?button('Özel Panelim','sector','data-sector="private"',ownerPanel==='private'?'selected':''):''}${Object.entries(names).map(([key,label])=>button(label,'sector',`data-sector="${key}"`,(config.audience==='owner'?ownerPanel===key:sector===key)?'selected':'')).join('')}</div>`:''}${!register&&config.audience!=='customer'?`<details class="auth-alternatives" ${loginMode==='phone'?'open':''}><summary>Telefonla giriş</summary><div class="sector auth-methods">${button('E-posta','login-method','data-method="email"',loginMode==='email'?'selected':'')}${button('Telefon','login-method','data-method="phone"',loginMode==='phone'?'selected':'')}</div></details>`:''}<form data-form="${register?'register':'login'}" data-login-mode="${loginMode}">${register?field('İşyeri adı','businessName','text','','required maxlength="120" autocomplete="organization"')+field('Yetkili adı','contactName','text','','required maxlength="120" autocomplete="name"'):''}${!register&&loginMode==='phone'?field('Kayıtlı telefon numaran','phone','tel','','required maxlength="40" autocomplete="username" inputmode="tel"'):field('E-posta','email','email',!register?localStorage.getItem('aesd.email.v2')||'':'','required maxlength="254" autocomplete="username"')}${field('Şifre','password','password','','required minlength="8" maxlength="128" autocomplete="'+(register?'new-password':'current-password')+'"')}${register?field('Şifre tekrar','confirm','password','','required minlength="8" autocomplete="new-password"')+`<div class="disclosure">Satıcının ciroyu görmesi isteğe bağlıdır. Paylaşırsan yalnız günlük satış toplamları, işlem sayısı, ödeme dağılımı ve iptal tutarı gönderilir. Müşteri adları ve ürün listeleri yönetim özetine dahil edilmez. Ortak satış, stok ve cari kayıtları eşitleme hizmetinin sunucusunda saklanır. Tercihini Ayarlar’dan kapatabilirsin.</div><p class="note">Şifre en az 8 karakter olmalı. Türkçe karakterlerde uzunluk sınırı daha erken dolabilir; üst sınır 72 UTF-8 baytıdır.</p><label class="check"><input name="consent" type="checkbox">Satış özetlerimi AESD yöneticisiyle paylaşmayı kabul ediyorum.</label><p class="note">Kayıt işyeri onayına gider. Onaydan sonra seçtiğin panelde ilk açılışla 24 saatlik deneme başlar. Diğer paneller ayrı lisans ister.</p>`:`<label class="check"><input name="remember" type="checkbox" >Beni hatırla</label>`}${submit(register?'Kayıt Oluştur':'Giriş Yap')}</form><p id="auth-error" class="error" role="alert"></p><div class="row spread">${config.audience==='owner'?'':button(register?'Zaten hesabım var':'İşyerini kaydet',register?'show-login':'show-register','','quiet')}${!register?button('Şifremi unuttum','forgot','','quiet'):''}</div></div>${config.audience==='all'?'<p class="contact"><a href="./staff.html">Personel girişi · yönetici cihaz onayı gerekir</a></p>':''}${contact()}${register?`<p class="muted contact">${escape(config.release)}</p>`:''}</section>`;
 const story=document.createElement('section');story.className='auth-story';story.innerHTML='<div class="auth-story-brand"><img src="./icon-192.png" width="48" height="48" alt=""><strong>AESD</strong></div><h2>İşinin tamamı.<br><span>Tek bir yerde.</span></h2><p>Satış, stok, cari hesaplar ve raporlar. İşletmeni kendi panelinden yönet.</p><small>Telefonda, tablette ve bilgisayarda.</small>';root.prepend(story);
 const password=root.querySelector('input[name=password]');
 if(password){const wrap=document.createElement('div');wrap.className='auth-password-field';password.replaceWith(wrap);wrap.append(password);const toggle=document.createElement('button');toggle.type='button';toggle.textContent='Göster';toggle.setAttribute('aria-label','Şifreyi göster');toggle.setAttribute('aria-pressed','false');toggle.addEventListener('click',()=>{const show=password.type==='password';password.type=show?'text':'password';toggle.textContent=show?'Gizle':'Göster';toggle.setAttribute('aria-label',show?'Şifreyi gizle':'Şifreyi göster');toggle.setAttribute('aria-pressed',String(show));});wrap.append(toggle);if(!register&&loginMode==='phone'){const hint=document.createElement('p');hint.id='auth-phone-hint';hint.className='note';hint.textContent='SMS kodu değil, AESD şifrenle giriş yap.';wrap.after(hint);password.setAttribute('aria-describedby',hint.id);}}
 updateAuthConnection();
}
function updateAuthConnection(){const form=root.querySelector('[data-form=login]');if(!form)return;const button=form.querySelector('[type=submit]'),error=root.querySelector('#auth-error');if(navigator.onLine===false){button.disabled=true;error.textContent='İnternet bağlantısı yok. Bağlantını kontrol ederek tekrar dene.';error.dataset.connection='offline';}else{button.disabled=busy;if(error.dataset.connection==='offline'){error.textContent='';delete error.dataset.connection;}}}
window.addEventListener('online',updateAuthConnection);window.addEventListener('offline',updateAuthConnection);
function syncText(){const text=syncMode==='queued'?'Ödeme cihazda kayıtlı · Eşitleme bekliyor':usingPrivate()&&!isShopManager()&&syncMode==='offline'?'Bağlantı yok · Ödeme cihazda kaydedilir':syncMode==='synced'?'Ortak kayıt güncel'+(syncTime?' · '+new Date(syncTime).toLocaleTimeString('tr-TR'):''):syncMode==='saving'?'Sunucu kaydı bekleniyor…':syncMode==='pending'?'İşlem sonucu bekleniyor. Yeni satış yapma.':'Ortak satış için internet gerekir.';return text+(isOwner()&&info?.staffAccess?.pendingCount?' · '+info.staffAccess.pendingCount+' personel cihazı onay bekliyor':'');}
