function panelChoices(){if(isShopManager())return '<p>Yalnız özel dükkân paneline erişimin var.</p>';return`<div class="panel-choices">${isOwner()?button(icon('private')+'<span>Özel Panelim</span>','owner-panel','data-panel="private"',usingPrivate()?'selected':''):''}${Object.entries(names).map(([key,label])=>button(icon(key)+`<span>${label}</span>`,isOwner()?'owner-panel':'open-panel',`data-panel="${key}" data-sector="${key}"`,!usingPrivate()&&sector===key?'selected':'')).join('')}</div>`;}
function tile(action,title,text='',extra='',glyph=action){return button(icon(glyph)+`<span>${escape(title)}${text?`<small>${escape(text)}</small>`:''}</span>`,action,extra,'tile');}
function openMenu(){
 if(!session)return;
 const privatePages=[['urunler','Ürün ve Stok','products'],['stok','Stok ve Alış','stock'],['cari','Müşteriler','customers'],['raporlar','Raporlar ve İptal','reports'],['musteriler','Müşteriler','customers'],['personel','Personel','customers'],['maliyet','İçindekiler','products'],['ayarlar','Yedek ve İşletme','backup']];
 const items=usingPrivate()?privatePages.map(([page,label,glyph])=>tile('private-page',label,'',`data-page="${page}"`,glyph)).join(''):allowed()&&store?[['products','Ürünler'],['stock','Stok ve Alış'],['customers','Cari Hesaplar'],['history','Satış ve İptal'],['reports','Raporlar'],['backup','Yedek'],['account-settings','Hesap ve Güvenlik']].map(([a,t])=>tile(a,t)).join(''):'';
 menu.innerHTML=`<div class="dialog-top"><div><div class="brand"><em>A</em>ESD</div><small>İşyerin için tüm işlemler</small></div>${button('×','close-menu','aria-label="Menüyü kapat"')}</div><h3>Paneller</h3>${panelChoices()}<h3>İşletme İşlemleri</h3><div class="menu-grid">${items||'<p class="muted">Önce yetkili panelini aç.</p>'}</div>${isOwner()?`<h3>Sistem Yönetimi <span class="badge">Yalnız sistem sahibi</span></h3><div class="menu-grid">${tile('shop-access','Dükkân erişimi','','','customers')}${tile('owner-admin','İşyeri ve Lisanslar','','','license')}${tile('owner-summaries','Paylaşılan Ciro','','','reports')}${tile('owner-audit','İşlem Geçmişi','','','history')}${tile('owner-staff','Personel ve Cihaz Onayı','','','customers')}${tile('account-customer-devices','Müşteri Cihazları','','','backup')}</div>`:''}<div class="menu-foot"><small>${escape(session.user.email)}</small></div>`;
 root.querySelector('[data-action=menu]')?.setAttribute('aria-expanded','true');if(!menu.open)menu.showModal();
}
async function switchOwnerPanel(panel){
 if(!isOwner())throw Error('Bu işlem yalnız sistem sahibine açıktır.');
 if(!['private',...Object.keys(names)].includes(panel))throw Error('Panel seçimi geçersiz.');
 if(panel===ownerPanel){closeMenu();if(panel==='private')await ownerSales();else if(store&&allowed())render();else await enter();return;}
 disposePrivate();sessionEpoch++;ownerPanel=panel;if(names[panel])sector=panel;category='';searchTerm='';resetBasket();hidePrivate();closeMenu();await persistSession();await enter();
}
async function refreshInfo(){const epoch=sessionEpoch,value=await api('/me');if(session.user&&session.user.role!==value.user.role){if(await clearSession())authView();const error=Error('Hesap yetkisi değişti. Tekrar giriş yap.');error.stale=true;throw error;}info=value;appearance.setAccount(info.user.id);session.user=info.user;session.business=info.business;await persistSession();assertCurrent(epoch);anchor(info.serverTime);if(isOwner()&&info.staffAccess){const incoming=info.staffAccess.pendingIds.filter(id=>!knownStaffRequests.has(id));for(const id of info.staffAccess.pendingIds)knownStaffRequests.add(id);syncStatus(syncMode,syncTime);if(incoming.length)toast(incoming.length+' yeni personel cihazı onay bekliyor. Ayarlar → Personel ve Cihaz Onayı.');}}
async function obtainLease(){
 const epoch=sessionEpoch,value=await api('/lease',{module:sector});anchor(value.serverTime);
 const publicKey=config.publicKey||value.publicKey;const checked=await verifyLease(value.token,publicKey,{businessId:privateUser()?privateScope():info.business.id,module:sector,deviceId,role:privateRole(),now:now()});
 assertCurrent(epoch);if(!checked)throw Error('Lisans imzası doğrulanmadı. Cihaz saatini ve WebView sürümünü kontrol edin.');lease={token:value.token,payload:checked};localStorage.setItem('aesd.lease.'+info.user.id,JSON.stringify({token:value.token,module:sector}));notice='';try{privateFrame?.contentWindow?.dispatchEvent(new Event('aesd-central-session'));}catch{}
}
async function cachedLease(){
 // A stored key is not a trust source. Offline launch requires the release key.
 const epoch=sessionEpoch;if(!config.publicKey||sector==='private')return false;try{const value=JSON.parse(localStorage.getItem('aesd.lease.'+session.user.id));if(value.module!==sector)return false;const checked=await verifyLease(value.token,config.publicKey,{businessId:session.user.role==='OWNER'?'owner:'+session.user.id:session.business.id,module:sector,deviceId,role:session.user.role,now:now(),offline:true});if(!checked||epoch!==sessionEpoch||!session)return false;lease={token:value.token,payload:checked};notice=session.user.role==='OWNER'?'Bağlantı yok. Özel panel satışları cihazda korunur.':'Bağlantı yok. Ortak satış için sunucu onayı gerekir.';return true;}catch{return false;}
}
function allowed(){const p=lease?.payload;if(p?.role==='SHOP_MANAGER'&&(!info?.shopAccess?.allowed||!navigator.onLine))return false;const until=p&&isOwner()&&(offlineConnectivity||!navigator.onLine)?p.offlineValidUntil||p.validUntil:p?.validUntil;const ok=p&&until>now()&&p.module===sector&&p.deviceId===deviceId;if(ok)localStorage.setItem('aesd.clock.v2',String(now()));return Boolean(ok);}
async function enter(){
 const epoch=sessionEpoch;try{await refreshInfo();if(isShopManager()){sector='private';ownerPanel='private';if(!info.shopAccess.allowed){shopGate();return;}}else if(accountUI.needsGate()){accountUI.gate();return;}await obtainLease();}catch(e){if(e.stale||e.accessDenied||epoch!==sessionEpoch)return;if(e.network&&await cachedLease()){info={user:session.user,business:session.business};}else{lease=null;if(e.status===401&&!e.uncertain){if(await clearSession())authView();toast(e.message);return;}panelGate(e.message);return;}}
 assertCurrent(epoch);const nextScope=(privateUser()?privateScope():info.business.id)+':'+sector;
 if(dataScope!==nextScope){resetBasket();store?.close();store=null;state=null;dataScope=nextScope;}
 window.aesdOwnerAllowed=()=>allowed()&&privateUser();window.aesdOwnerIdentity=()=>window.aesdOwnerAllowed()?{name:isShopManager()?info.user.email:'Sistem sahibi',role:'Yönetici'}:null;
 if(usingPrivate()){store?.close();store=null;state=null;tab='sales';await ownerSales();void resetUI.resume().catch(error=>toast(error.message));return;}
 store?.close();const active=await openCloudStore({businessId:panelBusiness().id,module:sector,api:(...args)=>{assertCurrent(epoch);return api(...args);},chooseMigration:data=>{assertCurrent(epoch);return chooseMigration(data);},onStatus:(mode,time)=>{if(epoch===sessionEpoch)syncStatus(mode,time);},onRecovered:pending=>{if(epoch===sessionEpoch&&pending.resetRejected){toast('Sıfırlama öncesi bekleyen işlem uygulanmadı. Yedek bölümünden cihaz kaydını indir.','error');return;}if(epoch===sessionEpoch&&pending.kind==='command'&&pending.data.type==='sale'){checkoutReview.recovered(pending.data.id);resetBasket();toast('Bekleyen satış sunucudan doğrulandı. Çift satış oluşturulmadı.');}}});if(epoch!==sessionEpoch){active.close();return;}store=active;try{const next=await active.initialize();assertCurrent(epoch,active);state=next;}catch(e){active.close();if(store===active)store=null;if(e.stale||e.accessDenied||epoch!==sessionEpoch)return;panelGate(e.message);return;}validateState(state,panelBusiness().id,sector);tab='sales';render(false);void syncSummary();void resetUI.resume().catch(error=>toast(error.message));
}
function panelGate(message=''){
 if(isShopManager()){if(!info.shopAccess.allowed){shopGate();return;}hidePrivate();closeMenu();root.className='';root.innerHTML=header('Dükkân bağlantısı')+'<main><section class="card"><h1>Dükkân bağlantısı</h1><p class="error">'+escape(message||'İnternete bağlanıp tekrar kontrol et.')+'</p>'+button('Tekrar kontrol et','retry')+button('Çıkış yap','logout')+'</section></main>';return;}
 if(accountUI.needsGate()){accountUI.gate();return;}
 hidePrivate();closeMenu();root.className='';const panels=info?.business?.panels||[];root.innerHTML=header(info?.business?.name||'Panel seçimi')+`<main><div class="card"><h1>Panel ve Aktivasyon</h1><p class="error">${escape(message)}</p><p class="muted">${escape(modes[info?.business?.state]||'Bağlantı ve lisans kontrolü gerekli.')}</p><div class="grid">${Object.entries(names).map(([key,label])=>{const p=panels.find(x=>x.module===key);return`<section class="card"><h2>${label}</h2><p>${escape(modes[p?.mode]||'Bağlantı bekleniyor')}</p><p class="muted">${p?.expires?'Bitiş: '+when(p.expires):p?.plan==='permanent'?'Süresiz':key===info?.business?.trialModule?'İlk açılışta 24 saat deneme':'Ayrı satın alma'}</p>${button('Paneli Aç','open-panel',`data-sector="${key}"`)} ${button('Aktivasyon','activation',`data-sector="${key}"`,'primary')}</section>`;}).join('')}</div>${button('Tekrar Kontrol Et','retry')}${button('Çıkış Yap','logout','','quiet')}${contact()}</div></main>`;
}
let summaryState=null,summaryValue=null;
function cachedSummary(value){if(summaryState!==value){summaryState=value;summaryValue=summary(value);}return summaryValue;}
function stats(){const rows=cachedSummary(state).days,today=dateKey(new Date()),day=rows.find(x=>x.date===today),month=rows.filter(x=>x.date.startsWith(today.slice(0,7))).reduce((n,x)=>n+x.netCents,0);return`<div class="stats stats-strip" aria-label="Günlük özet"><div class="stat"><span>Bugünkü Net Ciro</span><strong>${money(day?.netCents||0)}</strong></div><div class="stat"><span>Bu Ay</span><strong>${money(month)}</strong></div><div class="stat"><span>Bugünkü Satış</span><strong>${day?.salesCount||0}</strong></div></div>`;}
function basketView(){
 const total=cart.reduce((n,line)=>n+Math.round((state.products.find(p=>p.id===line.productId)?.priceCents||0)*line.qty),0);
 const count=cart.reduce((n,x)=>n+x.qty,0),needsCustomer=['credit','split'].includes(checkoutPayment),empty=!cart.length;
 return`<div class="basket-heading"><div>${icon(sector==='market'?'market':'orders')}<h2>${order?escape(order.label):sector==='market'?'Sepet':'Yeni Adisyon'}</h2></div><span class="badge">${count} ürün</span></div>${cart.length?cart.map(line=>{const p=state.products.find(x=>x.id===line.productId);return`<div class="line"><div class="row spread"><strong>${escape(p.name)}</strong><b>${money(Math.round(p.priceCents*line.qty))}</b></div><div class="row spread"><span>${line.qty} × ${money(p.priceCents)}</span><div class="quantity">${button('−','minus',`data-id="${p.id}" aria-label="${escape(p.name)} azalt"`)}${button('+','add',`data-id="${p.id}" aria-label="${escape(p.name)} artır"`)}</div></div></div>`;}).join(''):`<div class="basket-empty">${icon(sector==='market'?'market':'orders')}<p>Satış için ürün ekle.</p></div>`}<div class="basket-checkout"><div class="row spread basket-total"><span>Toplam</span><strong class="total">${money(total)}</strong></div>${empty?'':`<label for="payment">Ödeme</label><select id="payment">${options({cash:'Nakit',card:'Kart',credit:'Veresiye / Cari',other:'Diğer',split:'Parçalı Ödeme'},checkoutPayment)}</select>${checkoutPayment==='split'?`<fieldset><legend>Ödeme Dağılımı</legend>${Object.entries({cash:'Nakit',card:'Kart',credit:'Veresiye',other:'Diğer'}).map(([key,label])=>field(label+' (TL)','split_'+key,'number',checkoutAmounts[key],'min="0" step="0.01" required')).join('')}<p id="split-remaining" role="status">Dağılım toplamı satış tutarıyla eşleşmeli.</p></fieldset>`:''}${needsCustomer?`<label for="customer">Cari hesabı (veresiye için)</label><select id="customer"><option value="">Cari seç</option>${state.customers.map(c=>`<option value="${c.id}" ${c.id===checkoutCustomer?'selected':''}>${escape(c.name)}</option>`).join('')}</select>${field('Veresiye vadesi (isteğe bağlı)','sale-due','date',checkoutDue)}`:''}${state.warehouses?.length?`<label for="sale-warehouse">Satış deposu</label><select id="sale-warehouse"><option value="main">Ana depo</option>${state.warehouses.map(w=>`<option value="${w.id}" ${checkoutWarehouse===w.id?'selected':''}>${escape(w.name)}</option>`).join('')}</select>`:''}`}${button('Ödeme Özetine Geç','checkout',empty?'disabled aria-disabled="true"':'','primary full')}${!empty&&sector!=='market'?button('Adisyonu Kaydet','save-order','','full'):''}${!empty?button('Sepeti Temizle','clear-cart','','quiet full'):''}${!empty?`<p class="basket-note">${sector==='market'?'Ürün stoku düşer.':'Reçetedeki malzemeler stoktan düşer.'} Satış anındaki maliyet saklanır.</p>`:''}</div>`;
}
function categories(){if(!state.products.length)return'';const values=[...new Set(state.products.map(p=>p.category||'Genel'))];if(category&&!values.includes(category))category='';return`<div class="categories">${button('Tüm Ürünler','category','data-category=""',!category?'selected':'')}${values.map(c=>button(escape(c),'category',`data-category="${escape(c)}"`,category===c?'selected':'')).join('')}</div>`;}
function saleView(){return`<div class="page-heading sale-heading"><div><h1>${names[sector]} Satış</h1><p class="muted">${new Date().toLocaleDateString('tr-TR',{day:'numeric',month:'long',year:'numeric',timeZone:'Europe/Istanbul'})}</p></div>${sector!=='market'?button(icon('orders')+' Adisyonlar / Siparişler','orders','','quiet'):''}</div>${stats()}${notice?`<p class="note">${escape(notice)}</p>`:''}<div class="sale-layout"><section class="catalog-section"><div class="search-bar"><div>${field('Ürün adı veya barkod','search','search',searchTerm,'autocomplete="off" placeholder="Ürün ara veya barkodu okut…"')}</div>${button(icon('camera')+'<span>Kamera ile Tara</span>','camera')}</div>${sector!=='market'&&state.orders.length?`<div class="order-strip">${state.orders.map(o=>button(icon('orders')+` ${escape(o.label)}`,'load-order',`data-id="${o.id}"`)).join('')}</div>`:''}${categories()}<div class="catalog" id="catalog">${productTiles(searchTerm)}</div></section><aside class="basket card">${basketView()}</aside></div>`;}
function productTiles(filter){const list=state.products.filter(p=>(!category||(p.category||'Genel')===category)&&(p.name+' '+p.barcode).toLocaleLowerCase('tr').includes(filter.toLocaleLowerCase('tr')));return list.length?list.map(p=>`<button class="product" data-action="add" data-id="${p.id}"><div class="product-photo">${p.photo?`<img src="${escape(p.photo)}" alt="${escape(p.name)}" loading="lazy" width="256" height="192">`:icon(sector)}<span class="product-plus">+</span></div><div class="product-info"><small>${escape(p.category||'Genel')}</small><strong>${escape(p.name)}</strong><div class="row spread"><span class="price">${money(p.priceCents)}</span><small>${sector==='market'?'Stok: '+p.stock:p.recipe.length+' malzeme'}</small></div></div></button>`).join(''):`<div class="empty">${icon('products')}<h3>${state.products.length?'Ürün bulunamadı':'Ürünlerini ekleyerek başla'}</h3><p>${state.products.length?'Başka bir ad veya barkod ara.':'Ayarlar → Ürünler bölümünden ürün, fiyat ve fotoğraf ekle.'}</p>${!state.products.length?button('Ürün Ekle','products','','primary'):''}</div>`;}
function renderBasket(){saveCheckout();const basket=root.querySelector('.basket');if(basket)basket.innerHTML=basketView();else render();}
const resetUI=createBusinessResetUI({modal,api,escape,scope:()=>({token:session?.token,epoch:sessionEpoch,module:usingPrivate()?'private':sector,owner:isOwner(),name:usingPrivate()?'Özel Dükkânım':names[sector]}),pending:async()=>{const key=panelBusiness().id+':'+(usingPrivate()?'private':sector);return Boolean(await cloudMeta(key+':pending')||(usingPrivate()&&(await cloudMeta(key+':offline-v1'))?.queue?.length));},afterReset:async()=>{disposePrivate();store?.close();store=null;state=null;resetBasket();sessionEpoch++;dialog.close();await enter();toast('İşletme verileri sıfırlandı. Hesap ve lisanslar korundu.');}});
function settingsView(){const html=workspaceSettings({privatePanel:usingPrivate(),owner:isOwner(),title:panelBusiness().name,email:session.user.email,panel:sector,release:config.release});return isShopManager()?html.replace(/<button\b[^>]*data-action="(?:license|consent|workspace-panels)"[\s\S]*?<\/button>/g,''):html;}

function render(preserveCheckout=true){hidePrivate();closeMenu();if(preserveCheckout)saveCheckout();if(!allowed()){panelGate('Lisans kontrolü gerekli.');return;}root.className=tab==='sales'?'sale-shell':'settings-shell';root.innerHTML=header(panelBusiness().name)+`<main>${tab==='sales'?saleView():settingsView()}</main>`;}
async function execute(action){if(!allowed())throw Error('Lisans sona erdi. Sunucuya bağlanın.');const active=store,epoch=sessionEpoch,next=action.type==='refresh-only'?await active.read():await active.command(action);assertCurrent(epoch,active);state=next;void syncSummary();}
async function syncSummary(){if(!store||!info?.business?.consent||syncSummary.busy)return;const activeStore=store,epoch=sessionEpoch;syncSummary.busy=true;try{const current=await activeStore.read();if(store!==activeStore||epoch!==sessionEpoch||!info?.business?.consent)return;await api('/summary',summary(current));}catch{}finally{syncSummary.busy=false;}}
