function stockModal(){const items=sector==='market'?state.products:state.materials;modal('Stok ve Alış',`<div class="table-wrap"><table><tr><th>${sector==='market'?'Ürün':'Malzeme'}</th><th>Stok</th><th>Birim maliyet</th></tr>${items.map(p=>`<tr><td>${escape(p.name)} ${escape(p.unit||'adet')}</td><td>${p.stock}</td><td>${money(p.costCents)}</td></tr>`).join('')}</table></div>${sector!=='market'?`<form data-form="material">${field('Yeni malzeme adı','name','text','','required')}${field('Birim (gram / ml / adet)','unit','text','adet','required')}${submit('Malzeme Ekle')}</form><hr>`:''}<form data-form="purchase"><label for="itemId">Alınan ${sector==='market'?'ürün':'malzeme'}</label><select id="itemId" name="itemId" required>${items.map(p=>`<option value="${p.id}">${escape(p.name)}</option>`).join('')}</select>${field('Alış miktarı','qty','number','','required min="0.001" step="0.001"')}${field('Birim alış maliyeti (TL)','cost','number','','required min="0" step="0.01"')}${submit('Alışı Kaydet')}</form><p class="note">Yeni alış mevcut stokun ortalama maliyetini günceller. Geçmiş satış maliyetleri değişmez.</p>`);}
